# Extra practice for the core modules (Getting Started to Subqueries).
# These are appended after each module's original exercises, so existing exercise ids (and saved progress) never move.
# Every exercise has a variant on all six datasets and is verified by the build like the rest of the course.


def E(level, concepts, hint2, explain, order=True, **v):
    return dict(level=level, concepts=concepts, order=order, hint2=hint2, explain=explain, v=v)


